struct FeedClient: Sendable {
    var fetch: @Sendable (_ page: Int) async throws -> [Post]
}

extension FeedClient {
    static func live(session: URLSession) -> Self {
        Self { page in try await session.decode([Post].self, from: .feed(page: page)) }
    }
    static let preview = Self { _ in Post.samples }
    static let failing = Self { _ in throw URLError(.notConnectedToInternet) }
}

let model = FeedViewModel(client: .failing)   // test the error state
